<div class="admin-page-heading"><div><span class="admin-eyebrow">BUSINESS INFORMATION</span><p>Keep public contact details accurate. Leave fields blank until confirmed by the client.</p></div></div><section class="admin-panel form-panel"><form method="post" action="<?= e(url('/admin/settings')) ?>" class="admin-form-grid"><?= csrf_field() ?><label>Primary phone number<input name="phone_primary" value="<?= e($map['phone_primary']??'') ?>" placeholder="0547320593"></label><label>Secondary phone number<input name="phone_secondary" value="<?= e($map['phone_secondary']??'') ?>" placeholder="0596262939"></label><label>WhatsApp number (international format)<input name="whatsapp_number" value="<?= e($map['whatsapp_number']??'') ?>" placeholder="233547320593"><small>Ghana country code 233, without a leading zero.</small></label><label>Business email<input type="email" name="company_email" value="<?= e($map['company_email']??'') ?>"></label><label>Business location<input name="business_location" value="<?= e($map['business_location']??'Ghana') ?>"></label><label>Working hours<input name="working_hours" value="<?= e($map['working_hours']??'') ?>"></label><label>Instagram URL<input type="url" name="instagram_url" value="<?= e($map['instagram_url']??'') ?>" placeholder="https://instagram.com/..."></label><label>Facebook URL<input type="url" name="facebook_url" value="<?= e($map['facebook_url']??'') ?>" placeholder="https://facebook.com/..."></label><div class="span-2 admin-form-actions"><button class="admin-button" type="submit">Save Settings <span>→</span></button></div></form></section>
